<script>const jurisdiction=document.getElementById('jurisdiction'), municipality=document.getElementById('municipality'), selected=municipality.value; async function loadMunicipalities(){const response=await fetch(jurisdiction.dataset.municipalitiesUrl.replace('__id__',jurisdiction.value),{headers:{Accept:'application/json'}}); if(!response.ok)return; const units=await response.json(); municipality.replaceChildren(...units.map(unit=>new Option(`${unit.name} (${unit.code})`,unit.id, false,String(unit.id)===selected)));} jurisdiction.addEventListener('change',loadMunicipalities); loadMunicipalities();</script>
